const assert=require('node:assert/strict'),E=require('./engine.js'),fs=require('fs'),vm=require('vm');let n=0;const test=(name,f)=>{f();n++;console.log('PASS '+name)},bad=s=>E.validate(s).some(x=>x.level==='error');
test('Malformed record shapes reject without throwing',()=>{for(const mutate of [s=>s.people=[null],s=>s.costs={},s=>s.planned.Personnel=1,s=>s.people[0].changes=[null],s=>s.people[0].eff=[],s=>s.postedFa=[]]){let s=E.demo();mutate(s);assert(bad(s))}});
test('Assignment dates and salary changes validate',()=>{for(const mutate of [p=>p.start='2026-13',p=>{p.start='2027-01';p.end='2026-01'},p=>p.changes=[{month:'bad',salary:4}],p=>p.changes=[{month:'2026-01',salary:'bad'}],p=>p.eff={'2026-13':50}]){let s=E.demo();mutate(s.people[0]);assert(bad(s))}});
test('Unknown planned costs and modes reject',()=>{for(const mutate of [s=>s.costs[0].cat='Unknown',s=>s.planned.Unknown=[2],s=>s.grant.mode='other',s=>s.grant.base='other',s=>s.postedFa={'bad':10}]){let s=E.demo();mutate(s);assert(bad(s))}});
test('Monthly conservation across 250 randomized synthetic projects',()=>{let seed=47;const random=()=>{seed=(seed*16807)%2147483647;return seed/2147483647};for(let i=0;i<250;i++){let s=E.demo();s.grant.indirect=random()*70;s.grant.asOf=E.month(E.mi(s.grant.start)+Math.floor(random()*40));s.scenario={qty:Math.floor(random()*100)-50,cost:Math.floor(random()*100)-50};let c=E.calculate(s);assert.equal(c.curve.projected.at(-1),c.total.proj);assert.equal(E.cents(c.direct.proj)+E.cents(c.idc.proj),E.cents(c.total.proj));assert.equal(E.cents(c.total.plan)-E.cents(c.total.proj),E.cents(c.total.variance));assert(Object.values(c.total).filter(x=>typeof x==='number').every(Number.isFinite));}});
